function generate(rand, size) {
  const digit = pool => pool[Math.floor(rand() * pool.length)];
  const all = '0123456789', even = '02468', nonZero = '123456789', nonZeroEven = '2468';
  const n = size === 'large' ? 5000 + Math.floor(rand() * 5001) : 1 + Math.floor(rand() * 10);
  if (n === 1 && rand() < 0.15) return ['0'];
  const shape = rand();
  // Choose where the trailing run of even digits starts: anywhere, at the very start (no odd digit), or nowhere.
  const evenFrom = shape < 0.2 ? 0 : shape < 0.4 ? n : Math.floor(rand() * (n + 1));
  let num = '';
  for (let i = 0; i < n; i++) {
    if (i >= evenFrom) num += i === 0 ? digit(nonZeroEven) : digit(even);
    else if (i === evenFrom - 1) num += digit('13579');
    else num += i === 0 ? digit(nonZero) : digit(all);
  }
  return [num];
}
